mapper.select:
select

from safety.safety_park_power_rule sppr
left join safety.safety_group_info sgi on sgi.code = sppr.ORG_CODE and SGI.status = 'Y'
where 1 = 1 and sppr.is_delete = 0 and (coalesce(sppr.POST_NAME, '') != '' or coalesce(sppr.ORG_CODE, '') != '')


  order by ${orderByClause}




      limit ${offset}, ${limit}


      limit ${limit}

select * from( select M.emp_no,R.ID,R.FACTORY_POWER,R.PRIORITY,R.POST_NAME,R.ORG_CODE from safety_employee_message m ,safety_park_power_rule r where m.`status` = 'NORMAL' and r.IS_DELETE = 0 AND M.user_type = 'ZS' and m.position_name like CONCAT('%', r.POST_NAME, '%') and r.POST_NAME !=''
and m.emp_no in
#{item}
UNION ALL SELECT M.emp_no,R.ID,R.FACTORY_POWER,R.PRIORITY,R.POST_NAME,R.ORG_CODE FROM safety_employee_message m ,safety_park_power_rule r where m.`status` = 'NORMAL' and r.IS_DELETE = 0 AND M.user_type = 'ZS' and FIND_IN_SET(R.ORG_CODE, M.org_code_path) and r.ORG_CODE != ''
and m.emp_no in
#{item}
)tmp order by emp_no,PRIORITY
